import { OperationEditModal,OperationTrashScreen } from '../../src/components/OperationManagement';
import { PinLockModal } from '../../src/components/PinLockModal';
import { trashOperation,restoreOperation,isInTrash } from '../../src/utils/operationTrash';
import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import {OperationsDashboard,OperationOverview} from '../../src/components/OperationsDashboard';
import {Header} from '../../src/components/Header';
import {NewProjectModal} from '../../src/components/NewProjectModal';
import {CartaComprasScreen} from '../../src/components/CartaComprasScreen';
import {MenuScreen} from '../../src/components/MenuScreen';
import {VentasScreen} from '../../src/components/VentasScreen';
import {INITIAL_EVENTS,INITIAL_COCKTAILS,INITIAL_INGREDIENTS,DEFAULT_BUSINESS_PROFILE} from '../../src/data/initialData';
import {limaDate,eventInventory} from '../../src/utils/operationContext';
import {updateEventInventory} from '../../src/utils/ingredientImport';
import type {BarEvent,Cocktail,Ingredient} from '../../src/types/bar';
import '../../src/index.css';
const daily:BarEvent={...INITIAL_EVENTS[0],name:'Servicio habitual del bar',date:limaDate(),operationType:'dia'};
const party:BarEvent={...daily,id:'fixture-event',name:'Sunset Sessions',operationType:'evento',isConsignment:true,organizerName:'Promotor de ejemplo',inventory:[{ingredient:INITIAL_INGREDIENTS[0],receivedUnits:6,openedUnits:0}],orders:[],recipeSnapshot:[]};
const noop=()=>{};
function Fixture(){
 const [events,setEvents]=useState([daily,party,{...daily,id:'old-operation',name:'Jornada anterior sin clasificar',operationType:undefined}]);const [selected,setSelected]=useState(party.id);const [view,setView]=useState('home');const [create,setCreate]=useState<'dia'|'evento'|null>(null);
 const [editing,setEditing]=useState<string|null>(null);const [pinOpen,setPinOpen]=useState(false);const [authorised,setAuthorised]=useState(false);
 const trash=async(event:BarEvent)=>{setEvents(previous=>previous.map(e=>e.id===event.id?trashOperation(e):e));if(selected===event.id)setView('home');};
 const [barMenu,setBarMenu]=useState(INITIAL_COCKTAILS);const [barStock,setBarStock]=useState(INITIAL_INGREDIENTS);
 const active=events.find(e=>e.id===selected)!;const special=active.operationType==='evento';
 const menu=special?active.recipeSnapshot||[]:barMenu;const stock=special?eventInventory(active,barMenu):barStock;
 const save=(event:BarEvent)=>{setEvents(previous=>previous.some(e=>e.id===event.id)?previous.map(e=>e.id===event.id?event:e):[event,...previous]);setSelected(event.id);};
 const editMenu:React.Dispatch<React.SetStateAction<Cocktail[]>>=update=>{if(!special){setBarMenu(update);return;}setEvents(previous=>previous.map(event=>event.id===active.id?{...event,recipeSnapshot:typeof update==='function'?update(event.recipeSnapshot||[]):update}:event));};
 const editStock:React.Dispatch<React.SetStateAction<Ingredient[]>>=update=>{if(!special){setBarStock(update);return;}setEvents(previous=>previous.map(event=>{if(event.id!==active.id)return event;const current=eventInventory(event,barMenu);return {...event,inventory:updateEventInventory(event,current,typeof update==='function'?update(current):update,barStock)};}));};
 const currentView=view==='trash'?'papelera':view==='home'?'inicio':view==='overview'?'resumen':view==='config'?'carta_compras':view==='pos'?'pdv':'ventas';
 return <div className="h-dvh flex flex-col bg-[#faf8f5]"><Header currentView={currentView} activeEvent={active} contextLabel={view==='month'?'Panorama general':special?'Evento':'Bar habitual'} businessProfile={DEFAULT_BUSINESS_PROFILE} onChangeView={next=>setView(next==='inicio'?'home':next==='resumen'?'overview':next==='carta_compras'?'config':next==='pdv'?'pos':'metrics')} onOpenPublicMenu={noop} onOpenPrinterModal={noop} onOpenAssistant={noop} onOpenGuide={noop} onOpenMenuExcel={noop} onOpenOnboarding={noop}/><main className="flex flex-col flex-1 min-h-0">{view==='trash'&&authorised?<OperationTrashScreen events={events.filter(isInTrash)} onBack={()=>{setAuthorised(false);setView('home');}} onRestore={async event=>setEvents(previous=>previous.map(e=>e.id===event.id?restoreOperation(e):e))}/>:view==='home'?<OperationsDashboard onEdit={event=>setEditing(event.id)} onTrash={trash} onOpenTrash={()=>setPinOpen(true)} events={events} onOpen={event=>{setSelected(event.id);setView('overview');}} onCreate={setCreate} onMonth={()=>setView('month')}/>:view==='overview'?<OperationOverview onEdit={event=>setEditing(event.id)} onTrash={trash} key={active.id} event={active} cocktails={menu} catalog={barStock} onConfigure={()=>setView('config')} onOrders={()=>setView('pos')} onMetrics={()=>setView('metrics')} onSave={save} onClose={()=>save({...active,status:'closed',inventorySettledAt:Date.now()})}/>:view==='config'?<CartaComprasScreen key={active.id} inventoryScope={special?'evento':'bar'} contextId={active.id} contextName={active.name} barCocktails={barMenu} ingredientCatalog={barStock} cocktails={menu} setCocktails={editMenu} ingredients={stock} setIngredients={editStock} businessProfile={DEFAULT_BUSINESS_PROFILE}/>:view==='pos'?<MenuScreen menuScope={special?'evento':'bar'} cocktails={menu} ingredients={stock} businessProfile={DEFAULT_BUSINESS_PROFILE} onAddOrder={noop} onGoToCartaCompras={()=>setView('config')}/>:<VentasScreen activeEvent={active} allEvents={events} cocktails={menu} ingredients={stock} scope={view==='month'?'general':'context'} operationMode={view==='month'?'mes':'evento'} />}</main>{editing&&<OperationEditModal event={events.find(event=>event.id===editing)!} onSave={changes=>{const event=events.find(e=>e.id===changes.id)!;save({...event,...changes});}} onClose={()=>setEditing(null)}/>}<PinLockModal purpose="trash" isOpen={pinOpen} businessProfile={DEFAULT_BUSINESS_PROFILE} onClose={()=>setPinOpen(false)} onUnlock={()=>{setPinOpen(false);setAuthorised(true);setView('trash');}}/>{create&&<NewProjectModal initialType={create} fixedType isOpen ingredients={barStock} cocktails={barMenu} onClose={()=>setCreate(null)} onSaveEvent={event=>{save(event);setView('overview');}}/>}</div>;
}
createRoot(document.getElementById('root')!).render(<Fixture/>);
